    this.seconds = 0;
  }
  start() {
    setInterval(() => {
      this.seconds += 1;
      console.log(this.seconds);
    }, 1000);
  }
}
new Timer().start();
```

With this change, `this.seconds` properly accesses the `Timer` instance's `seconds` property, allowing the counter to increment correctly: 1, 2, 3, and beyond.

